export const rankName=r=>({11:'J',12:'Q',13:'K',14:'A',15:'Joker'})[r]||String(r);
export function topRank(pile){for(let i=pile.length-1;i>=0;i--)if(pile[i].rank!==15)return pile[i].rank;return null;}
export function legal(card,pile,lowTurns=0){const top=topRank(pile);return [2,15,10].includes(card.rank)||(lowTurns>0?card.rank<=7:(top===null||top===2||card.rank>=top));}
export function zone(p){return p.hand.length?'hand':p.up.length?'up':'down';}
export function createGame(rng=Math.random){const deck=[];for(const suit of ['♠','♥','♣','♦'])for(let rank=2;rank<=14;rank++)deck.push({id:suit+rank,rank,suit});deck.push({id:'joker-red',rank:15,suit:'♦'},{id:'joker-black',rank:15,suit:'♠'});for(let i=53;i>0;i--){let j=Math.floor(rng()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}const players=[0,1].map(()=>({hand:deck.splice(0,3),up:deck.splice(0,3),down:deck.splice(0,3)}));players[1].hand.push(...players[1].up);players[1].hand.sort((a,b)=>power(a)-power(b));players[1].up=players[1].hand.splice(3,3);return{deck,players,pile:[],lowTurns:0,direction:1,burned:[],turn:0,phase:'setup',winner:null,log:[],moves:0};}
const power=c=>({2:17,15:16,10:18})[c.rank]||c.rank;
export function start(g){g.phase='playing';g.turn=0;g.log=['Your deal. Play any card to open.'];}
export function swap(g,handId,upId){if(g.phase!=='setup')return false;const p=g.players[0],h=p.hand.findIndex(c=>c.id===handId),u=p.up.findIndex(c=>c.id===upId);if(h<0||u<0)return false;[p.hand[h],p.up[u]]=[p.up[u],p.hand[h]];return true;}
export function play(g,ids){if(g.phase!=='playing'||!ids.length)return {ok:false};const who=g.turn,p=g.players[who],z=zone(p),cards=ids.map(id=>p[z].find(c=>c.id===id));if(cards.some(c=>!c)||new Set(ids).size!==ids.length||cards.some(c=>c.rank!==cards[0].rank)||(z==='down'&&cards.length!==1))return{ok:false};if(z!=='down'&&!legal(cards[0],g.pile,g.lowTurns))return{ok:false};p[z]=p[z].filter(c=>!ids.includes(c.id));const name=who?'The Fox':'You';g.moves++;
if(z==='down'&&!legal(cards[0],g.pile,g.lowTurns)){p.hand.push(...g.pile,...cards);g.pile=[];g.lowTurns=0;g.turn=1-who;g.log.unshift(`${name} flipped ${rankName(cards[0].rank)} — and picked up the pile.`);return{ok:true,pickup:true,blind:cards[0]};}
if(cards[0].rank===7)g.lowTurns+=cards.length;else if(cards[0].rank!==15)g.lowTurns=Math.max(0,g.lowTurns-1);if(cards[0].rank===3&&cards.length%2)g.direction*=-1;g.pile.push(...cards);while(p.hand.length<3&&g.deck.length)p.hand.push(g.deck.pop());const last=g.pile.slice(-4),burn=cards[0].rank===10||(last.length===4&&last.every(c=>c.rank===last[0].rank));if(burn){g.burned.push(...g.pile);g.pile=[];g.lowTurns=0;}g.log.unshift(`${name} played ${cards.length>1?cards.length+' × ':''}${rankName(cards[0].rank)}${burn?' and burned the pile.':''}`);if(!p.hand.length&&!p.up.length&&!p.down.length){g.phase='finished';g.winner=who;g.log.unshift(who?'The Fox wins this one. Rematch?':'You escaped. The Fox is the Shithead.');}else g.turn=burn||cards[0].rank===3?who:1-who;return{ok:true,burn,cards};}
export function pickup(g){if(g.phase!=='playing'||!g.pile.length)return{ok:false};const who=g.turn;g.players[who].hand.push(...g.pile);g.pile=[];g.lowTurns=0;g.turn=1-who;g.moves++;g.log.unshift(`${who?'The Fox':'You'} picked up the pile.`);return{ok:true,pickup:true};}
const seenPositions=new WeakMap();
export function chooseMove(g,who=g.turn,rng=Math.random){const p=g.players[who],z=zone(p);let seen=seenPositions.get(g);if(!seen){seen=new Map();seenPositions.set(g,seen);}const signature=JSON.stringify([who,g.lowTurns,g.deck.length,g.pile.map(c=>c.id),p.hand.map(c=>c.id).sort(),p.up.map(c=>c.id).sort(),p.down.length,g.players[1-who].hand.length,g.players[1-who].up.map(c=>c.id).sort(),g.players[1-who].down.length]);const repeats=(seen.get(signature)||0)+1;seen.set(signature,repeats);if(seen.size>2000)seen.clear();if(repeats>2&&g.pile.length)return[];if(z==='down')return[p.down[Math.floor(rng()*p.down.length)].id];const options=p[z].filter(c=>legal(c,g.pile,g.lowTurns));if(!options.length)return[];options.sort((a,b)=>power(a)-power(b));const card=options[rng()<.12?Math.floor(rng()*options.length):0];return p[z].filter(c=>c.rank===card.rank).map(c=>c.id);}
export function assertGame(g){const all=[...g.deck,...g.pile,...g.burned,...g.players.flatMap(p=>[...p.hand,...p.up,...p.down])];if(all.length!==54||new Set(all.map(c=>c.id)).size!==54)throw Error('Card conservation failed');}
